//! W420 Bridge: runs the bundled sing-box sidecar (VLESS/VMess/Trojan/Shadowsocks/WireGuard/Hysteria2/TUIC/AnyTLS/OpenVPN ...)
//! The config is generated by the page (bridge-config.js); here it is validated with `sing-box check` and then run.
use serde::Serialize;
use std::io::{BufRead, BufReader, Write};
use std::path::PathBuf;
use std::process::{Child, Command, Stdio};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use tauri::Manager;
use w420_core::{build_config, parse_link, parse_ovpn, parse_profiles, parse_wireguard_conf, BuildOpts, VpnCreds};

pub struct Running {
    child: Child,
    started: Instant,
}

#[derive(Default)]
pub struct Bridge {
    pub proc: Mutex<Option<Running>>,
    pub log: Arc<Mutex<Vec<String>>>,
}

#[derive(Serialize)]
pub struct BridgeInfo {
    running: bool,
    pid: Option<u32>,
    uptime_s: u64,
    sidecar: Option<String>,
    elevated: bool,
    log_tail: Vec<String>,
}

fn triple() -> &'static str {
    if cfg!(all(target_os = "linux", target_arch = "x86_64")) { "x86_64-unknown-linux-gnu" }
    else if cfg!(all(target_os = "linux", target_arch = "aarch64")) { "aarch64-unknown-linux-gnu" }
    else if cfg!(all(target_os = "macos", target_arch = "x86_64")) { "x86_64-apple-darwin" }
    else if cfg!(all(target_os = "macos", target_arch = "aarch64")) { "aarch64-apple-darwin" }
    else if cfg!(all(target_os = "windows", target_arch = "x86_64")) { "x86_64-pc-windows-msvc" }
    else if cfg!(all(target_os = "windows", target_arch = "aarch64")) { "aarch64-pc-windows-msvc" }
    else { "unknown" }
}

/// Bundled sidecar: next to the executable (installed app), or src-tauri/binaries/<name>-<triple> (development).
pub fn find_sidecar(name: &str) -> Option<PathBuf> {
    let exe = if cfg!(windows) { format!("{name}.exe") } else { name.to_string() };
    if let Some(dir) = std::env::current_exe().ok().and_then(|p| p.parent().map(|d| d.to_path_buf())) {
        let p = dir.join(&exe);
        if p.is_file() { return Some(p); }
    }
    let dev = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("binaries").join(format!("{name}-{}{}", triple(), if cfg!(windows) { ".exe" } else { "" }));
    dev.is_file().then_some(dev)
}

/// True when the process may create a TUN device (root / administrator).
fn elevated() -> bool {
    #[cfg(unix)]
    { Command::new("id").arg("-u").output().map(|o| String::from_utf8_lossy(&o.stdout).trim() == "0").unwrap_or(false) }
    #[cfg(windows)]
    {
        let mut c = Command::new("net"); c.arg("session").stdout(Stdio::null()).stderr(Stdio::null());
        use std::os::windows::process::CommandExt; c.creation_flags(0x0800_0000);
        c.status().map(|s| s.success()).unwrap_or(false)
    }
}

/// TUN needs root/administrator, or on Linux the CAP_NET_ADMIN file capability on the sidecar (tools/grant-tun.sh).
fn tun_allowed(sb: &std::path::Path) -> bool {
    if elevated() { return true; }
    #[cfg(target_os = "linux")]
    { if let Ok(o) = Command::new("getcap").arg(sb).output() { return String::from_utf8_lossy(&o.stdout).contains("cap_net_admin"); } }
    let _ = sb;
    false
}

fn base_dir(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    let d = app.path().home_dir().map_err(|e| e.to_string())?.join(".w420").join("bridge");
    std::fs::create_dir_all(&d).map_err(|e| e.to_string())?;
    Ok(d)
}

fn hide(cmd: &mut Command) {
    #[cfg(windows)]
    { use std::os::windows::process::CommandExt; cmd.creation_flags(0x0800_0000); }
    #[cfg(not(windows))]
    { let _ = cmd; }
}

fn push_log(log: &Arc<Mutex<Vec<String>>>, line: String) {
    if let Ok(mut l) = log.lock() { l.push(line); let n = l.len(); if n > 300 { l.drain(0..n - 300); } }
}

fn pump(log: Arc<Mutex<Vec<String>>>, r: impl std::io::Read + Send + 'static) {
    std::thread::spawn(move || { for line in BufReader::new(r).lines().map_while(Result::ok) { push_log(&log, line); } });
}

/// Validates the generated config with the real engine, then starts it. The config holds secrets, so the file is private.
#[tauri::command]
pub fn bridge_start(app: tauri::AppHandle, state: tauri::State<Bridge>, config_json: String, tun: bool) -> Result<BridgeInfo, String> {
    start_impl(base_dir(&app)?, &state, &config_json, tun)
}

fn start_impl(dir: PathBuf, state: &Bridge, config_json: &str, tun: bool) -> Result<BridgeInfo, String> {
    let sb = find_sidecar("sing-box").ok_or("Не найден встроенный sing-box. Запусти: node tools/fetch-sidecars.mjs")?;
    if tun && !tun_allowed(&sb) {
        return Err("Системный режим (TUN) требует прав. Linux: bash tools/grant-tun.sh; Windows/macOS: запустите приложение от администратора. Либо используйте режим «Прокси».".into());
    }
    let mut guard = state.proc.lock().map_err(|_| "внутренняя ошибка")?;
    if let Some(r) = guard.as_mut() { if matches!(r.child.try_wait(), Ok(None)) { return Err("Мост уже запущен".into()); } }
    let cfg = dir.join("config.json");
    {
        #[cfg(unix)]
        use std::os::unix::fs::OpenOptionsExt;
        let mut o = std::fs::OpenOptions::new(); o.write(true).create(true).truncate(true);
        #[cfg(unix)]
        o.mode(0o600);
        o.open(&cfg).and_then(|mut f| f.write_all(config_json.as_bytes())).map_err(|e| e.to_string())?;
    }
    let mut chk = Command::new(&sb); chk.args(["check", "-c"]).arg(&cfg); hide(&mut chk);
    let out = chk.output().map_err(|e| format!("не удалось запустить sing-box: {e}"))?;
    if !out.status.success() {
        let msg = format!("{}{}", String::from_utf8_lossy(&out.stderr), String::from_utf8_lossy(&out.stdout));
        return Err(format!("Конфигурация не прошла проверку: {}", msg.trim().lines().last().unwrap_or("неизвестная ошибка")));
    }
    if let Ok(mut l) = state.log.lock() { l.clear(); }
    let mut cmd = Command::new(&sb);
    cmd.args(["run", "-c"]).arg(&cfg).current_dir(&dir).stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped());
    hide(&mut cmd);
    let mut child = cmd.spawn().map_err(|e| format!("не удалось запустить sing-box: {e}"))?;
    if let Some(o) = child.stdout.take() { pump(state.log.clone(), o); }
    if let Some(e) = child.stderr.take() { pump(state.log.clone(), e); }
    std::thread::sleep(Duration::from_millis(900));
    if let Ok(Some(status)) = child.try_wait() {
        let tail = state.log.lock().map(|l| l.iter().rev().take(3).cloned().collect::<Vec<_>>().join(" | ")).unwrap_or_default();
        return Err(format!("sing-box сразу завершился ({status}): {tail}"));
    }
    let pid = child.id();
    *guard = Some(Running { child, started: Instant::now() });
    drop(guard);
    Ok(info(state, Some(pid)))
}

fn info(state: &Bridge, pid: Option<u32>) -> BridgeInfo {
    let mut running = false; let mut up = 0; let mut p = pid;
    if let Ok(mut g) = state.proc.lock() {
        if let Some(r) = g.as_mut() {
            if matches!(r.child.try_wait(), Ok(None)) { running = true; up = r.started.elapsed().as_secs(); p = Some(r.child.id()); } else { p = None; }
        }
    }
    let tail = state.log.lock().map(|l| l.iter().rev().take(40).cloned().collect::<Vec<_>>()).unwrap_or_default();
    BridgeInfo { running, pid: p, uptime_s: up, sidecar: find_sidecar("sing-box").map(|p| p.display().to_string()), elevated: find_sidecar("sing-box").map(|p| tun_allowed(&p)).unwrap_or_else(elevated), log_tail: tail.into_iter().rev().collect() }
}

#[tauri::command]
pub fn bridge_status(state: tauri::State<Bridge>) -> BridgeInfo { info(&state, None) }

pub fn kill(state: &Bridge) {
    if let Ok(mut g) = state.proc.lock() { if let Some(mut r) = g.take() { let _ = r.child.kill(); let _ = r.child.wait(); } }
}

#[tauri::command]
pub fn bridge_stop(state: tauri::State<Bridge>) -> BridgeInfo { kill(&state); info(&state, None) }

/// Parses a single proxy / VPN link into a sing-box outbound/endpoint profile.
#[tauri::command]
pub fn config_parse_link(link: String) -> Result<serde_json::Value, String> {
    let profile = parse_link(&link).map_err(|e| e.to_string())?;
    serde_json::to_value(&profile).map_err(|e| e.to_string())
}

/// Parses many links (or a base64 subscription) into ok/bad lists.
#[tauri::command]
pub fn config_parse_profiles(text: String) -> Result<serde_json::Value, String> {
    let parsed = parse_profiles(&text).map_err(|e| e.to_string())?;
    serde_json::to_value(&parsed).map_err(|e| e.to_string())
}

/// Parses a WireGuard .conf into a sing-box endpoint profile.
#[tauri::command]
pub fn config_parse_wireguard(text: String, name: Option<String>) -> Result<serde_json::Value, String> {
    let profile = parse_wireguard_conf(&text, name.as_deref()).map_err(|e| e.to_string())?;
    serde_json::to_value(&profile).map_err(|e| e.to_string())
}

/// Parses an OpenVPN .ovpn into a sing-box client endpoint profile.
#[tauri::command]
pub fn config_parse_ovpn(text: String, name: Option<String>, username: Option<String>, password: Option<String>) -> Result<serde_json::Value, String> {
    let creds = username.as_ref().map(|u| VpnCreds { username: u.clone(), password: password.unwrap_or_default() });
    let (profile, needs_auth) = parse_ovpn(&text, name.as_deref(), creds.as_ref()).map_err(|e| e.to_string())?;
    let mut value = serde_json::to_value(&profile).map_err(|e| e.to_string())?;
    if let Some(obj) = value.as_object_mut() {
        obj.insert("needsAuth".into(), serde_json::json!(needs_auth));
    }
    Ok(value)
}

/// Builds a complete sing-box configuration JSON from profiles + options.
#[tauri::command]
pub fn config_build(profiles_json: String, opts_json: String) -> Result<String, String> {
    let profiles: Vec<w420_core::ProxyProfile> = serde_json::from_str(&profiles_json).map_err(|e| e.to_string())?;
    let opts: BuildOpts = serde_json::from_str(&opts_json).unwrap_or_default();
    let cfg = build_config(&profiles, &opts).map_err(|e| e.to_string())?;
    serde_json::to_string(&cfg).map_err(|e| e.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::{Read, Write};
    use std::net::TcpStream;

    fn socks_greeting(port: u16) -> Option<[u8; 2]> {
        for _ in 0..30 {
            if let Ok(mut s) = TcpStream::connect(("127.0.0.1", port)) {
                s.set_read_timeout(Some(Duration::from_secs(2))).ok();
                s.write_all(&[5, 1, 0]).ok();
                let mut b = [0u8; 2];
                if s.read_exact(&mut b).is_ok() { return Some(b); }
            }
            std::thread::sleep(Duration::from_millis(100));
        }
        None
    }

    #[test]
    fn rejects_bad_config_then_starts_serves_and_stops() {
        let dir = std::env::temp_dir().join(format!("w420-test-{}", std::process::id())).join("bridge");
        std::fs::create_dir_all(&dir).unwrap();
        assert!(find_sidecar("sing-box").is_some(), "sidecar missing: run node tools/fetch-sidecars.mjs");
        let st = Bridge::default();
        let good = include_str!("../tests/fixtures/proxy_ok.json");

        // 1) a config the engine rejects must be refused before anything starts
        let err = start_impl(dir.clone(), &st, include_str!("../tests/fixtures/bad.json"), false).err().expect("bad config accepted");
        assert!(err.contains("не прошла проверку"), "unexpected error: {err}");
        assert!(!info(&st, None).running);

        // 2) a good config starts, listens on the local proxy port and answers SOCKS5
        let i = start_impl(dir.clone(), &st, good, false).expect("start failed");
        assert!(i.running && i.pid.is_some());
        assert_eq!(socks_greeting(24080), Some([5, 0]), "local SOCKS5 proxy did not answer");
        assert!(start_impl(dir.clone(), &st, good, false).is_err(), "second start must be refused");
        assert!(info(&st, None).log_tail.iter().any(|l| l.contains("started")), "no log lines captured");

        // 3) the config file holds secrets and must be private
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = std::fs::metadata(dir.join("config.json")).unwrap().permissions().mode() & 0o777;
            assert_eq!(mode, 0o600, "config.json permissions are {mode:o}");
        }

        // 4) TUN without privileges must be refused with a clear message (only meaningful when not root)
        #[cfg(unix)]
        if !elevated() { assert!(start_impl(dir.clone(), &Bridge::default(), good, true).err().unwrap().contains("прав")); }

        // 5) stop really stops it
        kill(&st);
        assert!(!info(&st, None).running);
        std::thread::sleep(Duration::from_millis(300));
        assert!(TcpStream::connect(("127.0.0.1", 24080)).is_err(), "proxy still listening after stop");
    }
}
